from __future__ import annotations

MAX_DIM = 100
MIN_QUALITY = 30
GOOD_QUALITY = 60
SATURATION_LIMIT = 5

# Per-top-level-field predicates, keyed in the order they are validated so a
# field's own error name stays accurate.
GRID_FIELDS = {
    "width": lambda v: isinstance(v, int) and 1 <= v <= MAX_DIM,
    "height": lambda v: isinstance(v, int) and 1 <= v <= MAX_DIM,
    "cell_size": lambda v: isinstance(v, int) and 1 <= v,
}
OBS_FIELDS = ("x", "y", "value", "quality")


def accumulate_grid(raw: object) -> dict:
    if not isinstance(raw, dict):
        return {"ok": False, "error": "malformed input"}
    if any(field not in raw for field in ("grid", "observations", "fill_value")):
        return {"ok": False, "error": "missing field"}

    grid = raw["grid"]
    if not isinstance(grid, dict) or any(field not in grid for field in GRID_FIELDS):
        return {"ok": False, "error": "bad grid"}
    for field, ok in ((f, check(grid[f])) for f, check in GRID_FIELDS.items()):
        if not ok:
            return {"ok": False, "error": "bad " + field}

    cell_size = grid["cell_size"]
    if not isinstance(raw["fill_value"], int):
        return {"ok": False, "error": "bad fill value"}
    observations = raw["observations"]
    if not isinstance(observations, list):
        return {"ok": False, "error": "bad observations"}

    sums = {}
    counts = {}
    degraded = {}
    dropped = 0
    rejected = 0
    saturated = 0
    tolerance = cell_size // 2
    for obs in observations:
        if not isinstance(obs, dict) or any(
            field not in obs or not isinstance(obs[field], int) for field in OBS_FIELDS
        ):
            return {"ok": False, "error": "bad observation"}
        if not 0 <= obs["quality"] <= 100:
            return {"ok": False, "error": "bad observation"}
        if obs["quality"] < MIN_QUALITY:
            rejected = rejected + 1
            continue

        col, col_ok = _snap_coord(obs["x"], cell_size, grid["width"], tolerance)
        if not col_ok:
            dropped = dropped + 1
            continue
        row, row_ok = _snap_coord(obs["y"], cell_size, grid["height"], tolerance)
        if not row_ok:
            dropped = dropped + 1
            continue

        key = (row, col)
        if counts.get(key, 0) >= SATURATION_LIMIT:
            saturated = saturated + 1
            continue
        sums[key] = sums.get(key, 0) + obs["value"]
        counts[key] = counts.get(key, 0) + 1
        if obs["quality"] < GOOD_QUALITY:
            degraded[key] = True

    cells, flags = _build_grid(sums, counts, degraded, grid["width"], grid["height"], raw["fill_value"])
    total = grid["width"] * grid["height"]
    coverage = len(counts) * 100 // total
    line = ";".join(
        "{key}={value}".format(key=key, value=value)
        for key, value in (
            ("cells", total),
            ("filled", len(counts)),
            ("dropped", dropped),
            ("rejected", rejected),
            ("saturated", saturated),
            ("coverage", coverage),
        )
    )
    return {
        "ok": True,
        "cells": cells,
        "flags": flags,
        "dropped": dropped,
        "rejected": rejected,
        "saturated": saturated,
        "coverage": coverage,
        "line": line,
    }


